INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/jiuwudaishi-100-may-march/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002434；EPUB电子本，纸本及异文待核", "id": "e8f35e00-113d-5b0f-b315-5fbfb97263d9"}, {"title": "辽史·卷五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/liaoshi-005-shizong-accession/source.txt", "note": "《辽史》卷五，段落 liaoshi-7cd182a20e67-p000591；EPUB电子本，纸本及异文待核", "id": "cdaf1aee-bf3a-5f4a-bc95-501783656b1e"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/tongjian-287-947-may-opening/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003404；电子底本待考，分段待核", "id": "9fd4dc53-4bef-55f1-961b-193a9f58a37a"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/tongjian-287-947-southern-march/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003405；电子底本待考，分段待核", "id": "976d64d2-2573-5dc3-8ab9-6d43fac44d20"}, {"title": "新五代史·卷六十六", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/52874e45c7cb04fd601bd528e1c87122d4b092b3/content/books/zizhi-tongjian/vol-287/year-0947/part-01/sources/library/xinwudaishi-066-ma-xiguang-succession/source.txt", "note": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003327；EPUB电子本，纸本及异文待核", "id": "5aa66f11-cace-55d1-a2fc-966aefd49190"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/df264aefc4373c3f610c2f0bb525ac26f65cd07c/content/books/zizhi-tongjian/vol-286/year-0947/part-13/sources/library/jiuwudaishi-099-heyang-april/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002430；EPUB电子本，纸本及异文待核", "id": "73d07631-ce73-5399-890a-1e917e6cc33b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张砺。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "王晏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐州人，947年二月任奉国都头，与赵晖、侯章谋划杀死契丹将刘愿，率数名壮士夜入府署、取库中兵器。生卒年暂未录入。", "biography": null, "status": "draft", "id": "030a26f1-62e3-5876-92b4-923b763723f0"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "李存瑰", "aliases": ["李瓌", "李瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李存瑰，供奉官、赴西川赐诏者。", "biography": null, "status": "draft", "id": "a91449a7-a285-52aa-9c4a-0bf81e533f51"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "李骧", "aliases": ["李驤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，任河东幕僚。947年五月甲午任太原少尹，协助北京留守。生卒年未载。", "biography": null, "status": "draft", "id": "396c059d-a8b1-5901-8bea-7b2cad44203b"}, {"name": "蔚进", "aliases": ["蔚進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，原任牙将。947年五月甲午任马步指挥使，协助北京留守。生卒年未载。", "biography": null, "status": "draft", "id": "9bd69bc5-2939-5116-aa28-e159197eba5f"}, {"name": "刘晞", "aliases": ["劉晞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州人，在契丹曾任枢密使、同平章事及燕京留守。947年任西京留守，到洛阳后责斥奚王慢待赵在礼。与后晋官员刘昫字形、职务不同，暂不合并；生卒年未载。", "biography": null, "status": "draft", "id": "a5949823-5190-5e38-a780-eb04d4e680a5"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "张少敌", "aliases": ["張少敵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国天策都军使，张佶之子。941年十二月受马希范派遣，率一百五十艘战舰进入汉江，协助高行周讨安从进，并运粮供应。生卒年未载。", "biography": null, "status": "draft", "id": "e3c9c29f-0e6a-5dc5-a207-36eae30e98bb"}, {"name": "袁友恭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国都押牙。947年马希范去世后的继承争议中，与张少敌主张立较年长的马希萼。生卒年未载。", "biography": null, "status": "draft", "id": "1dfec000-c506-59f1-bbde-6b95499ae0c1"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "刘彦瑫", "aliases": ["劉彥瑫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国长直都指挥使。947年与李弘皋等主张拥立马希广，五月乙未称马希范遗命，拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "56a833a2-40b7-516a-baac-d3f00b328727"}, {"name": "李弘皋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。生卒年未载。", "biography": null, "status": "draft", "id": "87806f3c-0c40-510b-b333-2e0b18bc54da"}, {"name": "邓懿文", "aliases": ["鄧懿文"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国营田使，受马希范命登记逃亡民户留下的田地，招募民众耕种缴租。具体任职与行动年月未载。", "biography": null, "status": "draft", "id": "a5089609-5c2a-5e38-90e1-c6c7ab18b843"}, {"name": "杨涤", "aliases": ["楊滌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国小门使。947年马希范死后，与刘彦瑫等主张拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "011927f9-e8f2-562a-8e15-b5e9ccc7d716"}, {"name": "拓跋恒", "aliases": ["元恒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：拓跋恒，楚国仆射获任者。", "biography": null, "status": "draft", "id": "a53a8f9a-f7db-5e25-b74c-4b81973658e7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
